UPDATE TB_SYME001
SET
	HI_MNU_ID = #{map.menu.highMenuId}
	,MNU_NM = #{map.menu.menuName}
	,MNU_NM_EN = #{map.menu.menuNameEn}
	,MENU_ID = #{map.menu.menuId}
	,MNU_URL = #{map.menu.menuUrl}
	,ORD_PRI = #{map.menu.ordPriority}
	,MNU_DES = #{map.menu.menuDesc}
	,LINK_TP = #{map.menu.linkType}
	,UPD_DT= #{map.menu.writer.updateDate}
	,UPD_ID= #{map.menu.writer.updUserId}
WHERE MENU_ID = #{map.menuId}
